import{_ as a,H as i,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"17 | LLaMA3多智能体实战：如何构建一个多智能体系统？","description":"","frontmatter":{},"headers":[{"level":2,"title":"多智能体系统设计：智能体之间的最大区别是什么？","slug":"多智能体系统设计-智能体之间的最大区别是什么","link":"#多智能体系统设计-智能体之间的最大区别是什么","children":[{"level":3,"title":"合理分工：构建高效的智能体系统","slug":"合理分工-构建高效的智能体系统","link":"#合理分工-构建高效的智能体系统","children":[]},{"level":3,"title":"什么是种子记忆？","slug":"什么是种子记忆","link":"#什么是种子记忆","children":[]},{"level":3,"title":"种子记忆的作用","slug":"种子记忆的作用","link":"#种子记忆的作用","children":[]},{"level":3,"title":"种子记忆的实现方式","slug":"种子记忆的实现方式","link":"#种子记忆的实现方式","children":[]}]},{"level":2,"title":"智能体护栏：行为安全与稳定的保障","slug":"智能体护栏-行为安全与稳定的保障","link":"#智能体护栏-行为安全与稳定的保障","children":[{"level":3,"title":"护栏是怎么设计的？","slug":"护栏是怎么设计的","link":"#护栏是怎么设计的","children":[]}]},{"level":2,"title":"智能体系统的完整设计流程","slug":"智能体系统的完整设计流程","link":"#智能体系统的完整设计流程","children":[{"level":3,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}]}],"relativePath":"LLaMA3前沿模型实战课/17｜LLaMA3多智能体实战：如何构建一个多智能体系统？.md","filePath":"LLaMA3前沿模型实战课/17｜LLaMA3多智能体实战：如何构建一个多智能体系统？.md","lastUpdated":1795530715000}'),t={name:"LLaMA3前沿模型实战课/17｜LLaMA3多智能体实战：如何构建一个多智能体系统？.md"};function s(n,l,o,r,h,d){return i(),e("div",null,[...l[0]||(l[0]=[p(`<h1 id="_17-llama3多智能体实战-如何构建一个多智能体系统" tabindex="-1">17 | LLaMA3多智能体实战：如何构建一个多智能体系统？ <a class="header-anchor" href="#_17-llama3多智能体实战-如何构建一个多智能体系统" aria-label="Permalink to &quot;17 | LLaMA3多智能体实战：如何构建一个多智能体系统？&quot;">​</a></h1><p>你好，我是 Tyler！</p><p>在上一节课中，我们学习了多智能体系统的必要性，并探讨了如何通过引入多个智能体来提升系统的效率和灵活性。本节课我会带你深入理解开发过程中关键的设计方法和原则。</p><h2 id="多智能体系统设计-智能体之间的最大区别是什么" tabindex="-1">多智能体系统设计：智能体之间的最大区别是什么？ <a class="header-anchor" href="#多智能体系统设计-智能体之间的最大区别是什么" aria-label="Permalink to &quot;多智能体系统设计：智能体之间的最大区别是什么？&quot;">​</a></h2><p>在上一节课，我们提到 LLaMA 3 对智能体系统的优化要求我们遵循单一职责原则，而今天我们要深入探讨这个原则。设计多智能体系统时，最核心的问题之一是：智能体之间的最大区别是什么？答案是——人设（Persona）。</p><p>人设决定了每个智能体的角色和定位，也就是它在系统中具体要做的事情。你可以把人设想成公司里每个员工的岗位描述，通常包含以下几个重要元素：</p><ol><li><p>使命（Mission）：智能体的任务或目标，它告诉我们智能体存在的意义。举个例子，有的智能体的使命可能是“确保公司的合规运作”，另一个可能是“确保产品技术领先”。使命不仅明确了要做什么，还决定了任务的优先级和范围。</p></li><li><p>专业领域（Expertise）：智能体擅长的领域，类似于人类员工的专长。通过专注于某个领域，智能体能更高效地完成任务。</p></li><li><p>技能集（Skill Set）：智能体所具备的能力、工具和方法。例如，某些智能体擅长处理自然语言、访问外部 API，或者执行数据库查询等。技能集的不同让每个智能体能处理不同类型的任务，从而让系统更灵活。</p></li></ol><h3 id="合理分工-构建高效的智能体系统" tabindex="-1">合理分工：构建高效的智能体系统 <a class="header-anchor" href="#合理分工-构建高效的智能体系统" aria-label="Permalink to &quot;合理分工：构建高效的智能体系统&quot;">​</a></h3><p>在多智能体系统中，合理的分工非常重要。首先，我们得根据系统的需求分析任务的复杂度，然后把任务分成不同的模块，最后将这些模块分配给合适的智能体。这样，每个智能体都有清晰的职责，大家互相配合，才能让整个系统高效运行。</p><p>为了确保每个智能体都能稳定地完成任务，我们会用到种子记忆。</p><h3 id="什么是种子记忆" tabindex="-1">什么是种子记忆？ <a class="header-anchor" href="#什么是种子记忆" aria-label="Permalink to &quot;什么是种子记忆？&quot;">​</a></h3><p>种子记忆是指在智能体的提示词中埋入一些关键信息，作为智能体执行任务时的“记忆种子”。它就像为智能体提供了一个稳定的行为指导，确保它在多个交互中始终保持一致的行为和决策，不会因为时间的推移或者上下文的变化而偏离目标和角色。</p><h3 id="种子记忆的作用" tabindex="-1">种子记忆的作用 <a class="header-anchor" href="#种子记忆的作用" aria-label="Permalink to &quot;种子记忆的作用&quot;">​</a></h3><ol><li><p>稳定性：种子记忆可以帮助智能体保持其行为的一致性。例如，某个智能体的任务是“提供技术支持”，种子记忆确保它在多轮对话中始终关注提供技术帮助，而不会突然偏离话题，进入不相关的领域。</p></li><li><p>避免偏差：智能体在执行任务时，可能会受到外部输入的影响，从而出现不符合预期的行为。种子记忆为智能体提供了一个稳定的参考框架，帮助它抵抗不必要的干扰，减少误差和偏差的发生。</p></li><li><p>提高效率：通过种子记忆，智能体能够快速了解其角色和目标，从而在任务执行中更高效，不会因为重新定义目标或角色而浪费时间和资源。</p></li></ol><h3 id="种子记忆的实现方式" tabindex="-1">种子记忆的实现方式 <a class="header-anchor" href="#种子记忆的实现方式" aria-label="Permalink to &quot;种子记忆的实现方式&quot;">​</a></h3><p>通常，种子记忆是通过编写特定的提示词（prompt）来实现的。假设智能体扮演的是一个客户支持员工的角色，主要负责解答客户的咨询、处理售后问题、提供产品信息等。为了确保智能体在每次与客户的互动中始终符合员工角色的要求，我们为它设定了种子记忆，以确保它的行为和回答符合设定的员工职责。</p><p>这样，无论智能体与用户互动多少次，它都会根据这些信息执行任务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed_memory = &quot;&quot;&quot;</span></span></code></pre></div><ul><li>你是公司的一名客户支持员工。你的任务是提供高效、礼貌、专业的客户支持。无论客户提出什么问题，你都应</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 始终保持友好和专业的语气。</span></span>
<span class="line"><span>2. 为客户提供清晰、准确的信息，尽可能解决他们的问题。</span></span>
<span class="line"><span>3. 如果问题超出了你的知识范围，应主动引导客户联系其他专业团队或提供进一步帮助的途径。</span></span>
<span class="line"><span>4. 你不能提供任何超出公司政策或产品范围的承诺。</span></span>
<span class="line"><span>5. 你可以使用公司提供的FAQ和支持文档，但不能随意修改或猜测信息。</span></span></code></pre></div><ul><li><p>员工的行为规范：在与客户互动时，始终表现出耐心和尊重。避免过度推销或引导客户购买不必要的产品。</p></li><li><p>语言风格：简洁、礼貌、专业，不使用俚语或过于随意的语言。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;&quot;&quot;</span></span></code></pre></div><h2 id="智能体护栏-行为安全与稳定的保障" tabindex="-1">智能体护栏：行为安全与稳定的保障 <a class="header-anchor" href="#智能体护栏-行为安全与稳定的保障" aria-label="Permalink to &quot;智能体护栏：行为安全与稳定的保障&quot;">​</a></h2><p>在设计多智能体系统时，除了明确智能体的角色和任务，更重要的是确保它们的行为能够安全、稳定地执行。尤其是智能体直接参与任务时，任何异常行为都可能导致系统不稳定。因此，我们需要引入“智能体护栏”（Guardrails）来限制智能体的行为，你可以把智能体护栏想象成是火车的轨道。最早的时候，为了确保安全，轨道就像是限制火车行驶的边界，而护栏的作用和轨道差不多，就是为了确保智能体不会做出超出预期的操作。</p><p>护栏的重要性体现在几个方面：</p><ol><li><p>防止错误决策：有时候，智能体可能会因为数据误判或算法偏差，做出错误的决策，导致生产系统出问题。没有护栏的情况下，这些错误的决策可能会带来严重后果。护栏的作用就是防止这种情况发生，确保智能体的决策符合预期。</p></li><li><p>保障系统稳定性：智能体通常需要在在线环境中长时间、高频率地工作。如果它们做出了不合适的行为，可能会导致整个系统的崩溃或不稳定。通过设置护栏，可以减少这种异常操作的发生，从而确保系统的稳定性和可靠性。</p></li></ol><h3 id="护栏是怎么设计的" tabindex="-1">护栏是怎么设计的？ <a class="header-anchor" href="#护栏是怎么设计的" aria-label="Permalink to &quot;护栏是怎么设计的？&quot;">​</a></h3><p>设计智能体护栏时，需要综合考虑智能体的任务需求以及它们的行为规范。这里的行为规范是指每个智能体都应该有明确的行为边界，确保它们只做自己被允许做的事。比如，订单处理系统中的智能体，只能修改订单的特定字段，而不能删除订单。我们可以通过规则引擎或者策略表来定义这些限制，确保智能体的行为在预定范围内。</p><p>为了确保智能体的行为符合预期，系统会实时监控它们的操作。通过记录操作日志并分析智能体的行为，可以及时发现问题。如果发现异常，系统可以立即发出警报，或者执行回滚操作，防止异常行为影响系统的正常运行。</p><p>在一些行业内，智能体护栏显得尤为重要，比如金融行业。智能体可能会涉及客户咨询或投资建议等任务，但并非所有智能体都具备金融专业知识。如果没有护栏，智能体可能会给客户提供错误的投资建议，带来风险。通过护栏程序，我们可以限制智能体的讨论内容，确保它们不会“胡说八道”。</p><h2 id="智能体系统的完整设计流程" tabindex="-1">智能体系统的完整设计流程 <a class="header-anchor" href="#智能体系统的完整设计流程" aria-label="Permalink to &quot;智能体系统的完整设计流程&quot;">​</a></h2><p>在了解了人设和护栏的重要性之后，我把多智能体系统的完整流程整理成一张图片，你可以参考。</p><ol><li>明确需求</li></ol><ul><li><p>分析系统的整体目标和需要解决的核心问题。</p></li><li><p>将目标任务分解为多个模块，为智能体的分工设计提供基础。</p></li></ul><ol start="2"><li>设计人设</li></ol><ul><li><p>针对每个任务模块，定义智能体的使命、专业领域和技能集。</p></li><li><p>确保人设之间的职责明确，无交叉或冲突。</p></li></ul><ol start="3"><li>配置护栏</li></ol><ul><li><p>针对每个智能体设计行为边界，防止权限滥用和不必要的操作。</p></li><li><p>定义智能体的权限范围和具体操作限制。</p></li></ul><ol start="4"><li>构建交互机制</li></ol><ul><li><p>设计智能体之间的通信协议。例如，使用消息队列、共享内存或事件驱动机制。</p></li><li><p>确保智能体能够高效协作。</p></li></ul><ol start="5"><li>测试与优化</li></ol><ul><li><p>在模拟环境中运行多智能体系统，观察其行为。</p></li><li><p>根据测试结果调整人设和护栏，优化整体性能。</p></li></ul><ol start="6"><li>上线运行</li></ol><ul><li><p>将经过测试的智能体部署到生产环境，并配置监控工具。</p></li><li><p>持续收集运行数据，以便改进系统的稳定性和可靠性。</p></li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>学到这里，我们做个总结吧。在多智能体系统的设计中，人设和种子记忆的应用是确保智能体行为一致性和任务执行稳定性的关键。通过合理分工、明确角色设定和行为规范，可以让每个智能体在复杂的系统中高效运作。</p><p>设计一个多智能体系统，不仅要考虑智能体的能力和任务，还要确保它们在实际应用中的稳定性和安全性。使智能体可以在复杂的系统环境中协同工作，完成各自的任务。在实际操作中，通过智能体行为的规范和种子记忆的持续维护，可以最大程度地避免系统中的偏差和风险，提升整体效率。</p><p>课程即将接近尾声，后续的任务也会变得越来越复杂。在这里，我想提前预告一下，即使在课程结束后，大家依然可以通过访问我的 GitHub 仓库，继续获得不断更新的示例。对于一些有趣的示例，我们也会不定期进行更新。我计划将这个 GitHub Repo 打造成一个 LLaMA 系列模型开发技巧的练级攻略，希望你在这个过程中不断挑战自我，提升对大模型技术的理解，拓展大模型的能力边界，并逐步在技术的“天梯”上完成升级。</p><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>根据今天学习的种子记忆和护栏技术，试着构建一个多智能体系统。我的实现会在 GitHub 上发布，你可以参考并对比。提示：你可以使用 LangGraph 或 Dify 这样的智能体系统来进行低代码建模。</p><p>欢迎你把你构建的智能体系统发布在留言区，我们一起交流探讨，如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>`,51)])])}const _=a(t,[["render",s]]);export{c as __pageData,_ as default};
